import java.util.ArrayList;
import java.util.List;

// Demonstrating the flaws of Cloneable and the superiority of Copy Constructors
public class DeepCopyDemo {

    // 1. THE FLAWED APPROACH: Using Cloneable
    public static class Order implements Cloneable {
        private String orderId;
        private List<String> items;

        public Order(String orderId, List<String> items) {
            this.orderId = orderId;
            this.items = items;
        }

        // Must override clone(), change visibility to public, and handle checked exception
        @Override
        @SuppressWarnings("unchecked")
        public Order clone() {
            try {
                Order cloned = (Order) super.clone(); // Bitwise shallow copy
                // Manual deep copy of mutable list to prevent shared reference
                cloned.items = new ArrayList<>(this.items); 
                return cloned;
            } catch (CloneNotSupportedException e) {
                // This should never happen since we implement Cloneable
                throw new AssertionError("Clone failed on Cloneable object", e);
            }
        }
    }

    // 2. THE PRODUCTION-GRADE APPROACH: Copy Constructor
    public static class UserProfile {
        private final String username;
        private final List<String> roles; // final field

        public UserProfile(String username, List<String> roles) {
            this.username = username;
            this.roles = new ArrayList<>(roles);
        }

        // Copy Constructor: Clean, safe, handles final fields, no checked exceptions
        public UserProfile(UserProfile other) {
            this.username = other.username;
            // Deep copy of mutable list is perfectly valid here even though 'roles' is final
            this.roles = new ArrayList<>(other.roles); 
        }

        public List<String> getRoles() {
            return roles;
        }
    }
}
